// Reads src/content/** and writes the files that gather it, so a new building is just a new folder:
//   src/content/buildings/<kind>/building.json   numbers, rules and levels of the building
//   src/content/buildings/<kind>/L1.json ...     its drawings, one per stone level (L1open.json: the same gate standing open)
//   src/content/buildings/<kind>/A1.json         its drawing of the first medieval level (A1open.json: the gate open)
// Run by build.mjs and the viewer builds; the two generated files are kept in git so that tsc and the tests see them too.
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const dir = join('src', 'content', 'buildings');
const kinds = readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory() && existsSync(join(dir, d.name, 'building.json'))).map((d) => d.name).sort();
const artOf = (k, prefix = 'L') => readdirSync(join(dir, k)).filter((f) => new RegExp('^' + prefix + '\\d+(open)?\\.json$').test(f) && readFileSync(join(dir, k, f), 'utf8').trim() !== '')
  .sort((a, b) => (/open/.test(a) - /open/.test(b)) || parseInt(a.slice(1)) - parseInt(b.slice(1)));
const id = (k) => k.replace(/[^A-Za-z0-9]/g, '_');
const head = '// GENERATED by tools/gen-content.mjs from src/content/buildings/*: do not edit by hand.\n';

writeFileSync(join(dir, 'defs.gen.ts'), head
  + kinds.map((k) => `import ${id(k)} from './${k}/building.json';`).join('\n')
  + `\nexport const BUILDING_KINDS = [${kinds.map((k) => `'${k}'`).join(', ')}] as const;\n`
  + `export const BUILDING_FILES: Record<string, unknown> = { ${kinds.map((k) => `${k}: ${id(k)}`).join(', ')} };\n`);

const imports = [], rows = [], arows = [];
const rowOf = (k, files) => `  ${k}: [${files.map((f) => `${id(k)}_${f.replace('.json', '')}`).join(', ')}],`;
for (const k of kinds) {
  const files = artOf(k), afiles = artOf(k, 'A');
  for (const f of [...files, ...afiles]) imports.push(`import ${id(k)}_${f.replace('.json', '')} from './${k}/${f}';`);
  rows.push(rowOf(k, files));
  if (afiles.length) arows.push(rowOf(k, afiles));
}
writeFileSync(join(dir, 'art.gen.ts'), head + imports.join('\n')
  + '\n/** Drawings of each kind in the stone age, one per level (a gate lists its open drawings after the shut ones). */\n'
  + `export const STONE_ART: Record<string, unknown[]> = {\n${rows.join('\n')}\n};\n`
  + '/** Drawings of the first medieval level (level 5): A1.json, and for a gate its open drawing after the shut one. */\n'
  + `export const ANCIENT_ART: Record<string, unknown[]> = {\n${arows.join('\n')}\n};\n`);
console.log('content: ' + kinds.length + ' buildings');
